import{_ as e,c as a,o,ae as s}from"./chunks/framework.CliRSA9F.js";const r="/images/LUCIA_example_chat.webp",m=JSON.parse(`{"title":"LUCIA — Your Podcast Assistant","description":"Use LUCIA to understand your podcast data, manage keywords, positioning, competitors, PR outreach, notifications, and episode plans, and learn your plan's monthly message allowance.","frontmatter":{"description":"Use LUCIA to understand your podcast data, manage keywords, positioning, competitors, PR outreach, notifications, and episode plans, and learn your plan's monthly message allowance."},"headers":[],"relativePath":"features/lucia-ai-assistant.md","filePath":"features/lucia-ai-assistant.md"}`),i={name:"features/lucia-ai-assistant.md"};function n(d,t,c,l,h,p){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="lucia-—-your-podcast-assistant" tabindex="-1">LUCIA — Your Podcast Assistant <a class="header-anchor" href="#lucia-—-your-podcast-assistant" aria-label="Permalink to &quot;LUCIA — Your Podcast Assistant&quot;">​</a></h1><p>Open <strong>Chat</strong> in the sidebar to work with LUCIA. It can use the selected podcast&#39;s positioning, keywords, rankings, competitors, and episode plans to answer questions and make supported changes in PodSEO.</p><p><img src="'+r+'" alt="LUCIA Chat Interface" width="600px" style="display:block;margin:0 auto;"></p><h2 id="start-with-the-right-podcast" tabindex="-1">Start with the right podcast <a class="header-anchor" href="#start-with-the-right-podcast" aria-label="Permalink to &quot;Start with the right podcast&quot;">​</a></h2><p>Select your podcast and, if applicable, your organization account before opening chat. Name the episode or keyword when a request could apply to several items. A useful first request is: “Summarize my current keyword strategy and tell me which three changes to consider next.”</p><h2 id="ask-about-your-data" tabindex="-1">Ask about your data <a class="header-anchor" href="#ask-about-your-data" aria-label="Permalink to &quot;Ask about your data&quot;">​</a></h2><p>LUCIA can help explain rankings and their history, metadata alignment, competitor overlap, distribution issues, AI visibility, reviews, and plan allowances. You can also ask about credit usage or the status of clip creation.</p><p>Ask for the platform and period behind a comparison: “Which of my tracked keywords dropped on Spotify?” is more actionable than “Why am I not growing?” If the data is incomplete, inspect the relevant feature page before drawing a conclusion.</p><h2 id="ask-lucia-to-make-changes" tabindex="-1">Ask LUCIA to make changes <a class="header-anchor" href="#ask-lucia-to-make-changes" aria-label="Permalink to &quot;Ask LUCIA to make changes&quot;">​</a></h2><p>You can request actions as well as advice:</p><table tabindex="0"><thead><tr><th>Task</th><th>Example request</th></tr></thead><tbody><tr><td>Track keywords</td><td>“Track beginner investing and retirement planning.”</td></tr><tr><td>Assign keywords</td><td>“Use retirement planning as a show keyword,” or “Assign my host name as brand.”</td></tr><tr><td>Stop tracking</td><td>“Stop tracking the keyword daily stock picks.”</td></tr><tr><td>Organize groups</td><td>“Create a Retirement group and add my retirement planning keyword.”</td></tr><tr><td>Update positioning</td><td>“Update my target audience to first-time investors in their thirties.”</td></tr><tr><td>Create an episode plan</td><td>“Create an idea for an episode about building an emergency fund.”</td></tr><tr><td>Edit a plan</td><td>“Move the emergency fund episode to next Friday and update its description.”</td></tr><tr><td>Manage existing plans</td><td>“Duplicate this episode plan,” or “Link this plan to the published episode.”</td></tr><tr><td>Reschedule plans</td><td>“Move my overdue episode plans to next week.”</td></tr><tr><td>Target episode keywords</td><td>“Add retirement planning as a keyword for the emergency fund episode.”</td></tr><tr><td>Suggest episode titles</td><td>“Suggest a title for the emergency fund episode from its keywords.”</td></tr><tr><td>Add competitors</td><td>“Add The Money Hour as a competitor.”</td></tr><tr><td>Manage PR outreach</td><td>“Add this newsletter to my outreach pipeline and remind me to follow up next Tuesday.”</td></tr><tr><td>Act on recommendations</td><td>“Dismiss the recommendation about my show description,” or “Mark the artwork recommendation as done.”</td></tr><tr><td>Review collection</td><td>“Start collecting reviews for my podcast.”</td></tr><tr><td>Refresh your feed</td><td>“Refresh my RSS feed so the new episode shows up.”</td></tr><tr><td>Notification settings</td><td>“Send Pulse news in my weekly digest instead of as it happens.”</td></tr><tr><td>Send feedback</td><td>“Tell the PodSEO team the calendar view should show time zones.”</td></tr></tbody></table><p>Be explicit about whether you want suggestions or saved changes. Review the result in Keyword Strategy, Show Rankings, Positioning, or Planner after an action. A title LUCIA proposes in chat isn&#39;t saved until you see the action result — check the record to be sure.</p><p>LUCIA follows the same access and plan limits as the app. It cannot bypass your total keyword allowance, paid episode features, podcast assignments, or approval requirements. Archiving a linked or published plan requires resolving its link first.</p><h2 id="what-changes-outside-podseo" tabindex="-1">What changes outside PodSEO? <a class="header-anchor" href="#what-changes-outside-podseo" aria-label="Permalink to &quot;What changes outside PodSEO?&quot;">​</a></h2><p>Saving a plan or changing keywords in PodSEO does not update your podcast host, rewrite the live RSS feed, or publish an episode. Apply approved title and description changes in your host separately. Use <a href="/features/social-publishing.html">Social Publishing</a> to review and schedule social posts, and <a href="/features/agency-workspace.html">Agency approvals</a> for client sign-off.</p><h2 id="availability-and-limits" tabindex="-1">Availability and limits <a class="header-anchor" href="#availability-and-limits" aria-label="Permalink to &quot;Availability and limits&quot;">​</a></h2><p>LUCIA has a monthly message allowance based on your plan:</p><table tabindex="0"><thead><tr><th>Plan</th><th>Messages per month</th></tr></thead><tbody><tr><td>Free</td><td>5</td></tr><tr><td>Podcaster</td><td>300</td></tr><tr><td>Producer</td><td>1,000</td></tr><tr><td>Agency</td><td>10,000</td></tr><tr><td>Enterprise</td><td>See your plan or contact us</td></tr></tbody></table><p>Ask LUCIA about your current allowance, or check your account when you encounter a limit. Clip-generation credits are a separate allowance; see <a href="/features/billing-and-account.html">Billing and Account Settings</a>.</p><p>In a team, use your own login and the correct organization context. Share only information needed for the task, and check the current privacy policy for how the service handles conversation data. LUCIA&#39;s answers can be mistaken: verify important recommendations and distinguish an observed ranking change from proof of its cause.</p><h2 id="if-an-action-fails" tabindex="-1">If an action fails <a class="header-anchor" href="#if-an-action-fails" aria-label="Permalink to &quot;If an action fails&quot;">​</a></h2><p>Read the response for the affected item and limit. Check the selected podcast, your permissions, and available capacity, then open the feature directly to confirm its state before retrying. For a persistent issue, contact PodSEO through <strong>Settings → Contact Us</strong> with the request and the affected podcast.</p>',22)])])}const g=e(i,[["render",n]]);export{m as __pageData,g as default};
